const base=require('./practice_test_03.cjs');
const form=`import {useId,useRef,useState,type FormEvent} from "react";export type FormValues={title:string;description:string;priority:"LOW"|"NORMAL"|"HIGH"|"CRITICAL"};type Errors={title?:string;description?:string;form?:string};export function NewTicketForm({onCreate,onCreated}:{onCreate:(values:FormValues)=>Promise<void>;onCreated?:()=>void}){const prefix=useId(),titleRef=useRef<HTMLInputElement>(null),descriptionRef=useRef<HTMLTextAreaElement>(null),sending=useRef(false);const [title,setTitle]=useState(""),[description,setDescription]=useState(""),[priority,setPriority]=useState<FormValues["priority"]>("NORMAL"),[errors,setErrors]=useState<Errors>({}),[busy,setBusy]=useState(false);async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();if(sending.current)return;const inputTitle=title.trim(),inputDescription=description.trim();if(inputTitle.length<5){setErrors({title:"Tytuł musi mieć co najmniej 5 znaków."});titleRef.current?.focus();return;}if(priority==="CRITICAL"&&inputDescription.length<10){setErrors({description:"Krytyczny ticket wymaga opisu co najmniej 10 znaków."});descriptionRef.current?.focus();return;}sending.current=true;setBusy(true);setErrors({});try{await onCreate({title:inputTitle,description:inputDescription,priority});setTitle("");setDescription("");setPriority("NORMAL");onCreated?.();}catch{setErrors({form:"Nie udało się utworzyć ticketu. Dane pozostają w formularzu."});}finally{sending.current=false;setBusy(false);}}return <form noValidate onSubmit={submit}><label htmlFor={prefix+"-title"}>Tytuł</label><input ref={titleRef} id={prefix+"-title"} value={title} disabled={busy} aria-invalid={!!errors.title} aria-describedby={errors.title?prefix+"-title-error":undefined} onChange={e=>setTitle(e.currentTarget.value)}/>{errors.title&&<p id={prefix+"-title-error"} role="alert">{errors.title}</p>}<label htmlFor={prefix+"-description"}>Opis</label><textarea ref={descriptionRef} id={prefix+"-description"} value={description} disabled={busy} aria-invalid={!!errors.description} aria-describedby={errors.description?prefix+"-description-error":undefined} onChange={e=>setDescription(e.currentTarget.value)}/>{errors.description&&<p id={prefix+"-description-error"} role="alert">{errors.description}</p>}<label htmlFor={prefix+"-priority"}>Priorytet</label><select id={prefix+"-priority"} value={priority} disabled={busy} onChange={e=>{const raw=e.currentTarget.value;if(raw==="LOW"||raw==="NORMAL"||raw==="HIGH"||raw==="CRITICAL")setPriority(raw);}}>{["LOW","NORMAL","HIGH","CRITICAL"].map(value=><option key={value}>{value}</option>)}</select>{errors.form&&<p role="alert">{errors.form}</p>}<button type="submit" disabled={busy}>{busy?"Tworzenie…":"Utwórz"}</button></form>;}`;
const tabs=`import {useId,useRef,useState,type KeyboardEvent} from "react";const names=["Szczegóły","Aktywność","Historia"];export function TicketSections(){const prefix=useId(),refs=useRef<Array<HTMLButtonElement|null>>([]);const [active,setActive]=useState(0);function keyboard(event:KeyboardEvent<HTMLButtonElement>){let next=active;if(event.key==="ArrowRight")next=(active+1)%names.length;else if(event.key==="ArrowLeft")next=(active+names.length-1)%names.length;else if(event.key==="Home")next=0;else if(event.key==="End")next=names.length-1;else return;event.preventDefault();setActive(next);refs.current[next]?.focus();}return <section><div role="tablist" aria-label="Sekcje ticketu">{names.map((name,index)=><button key={name} ref={node=>{refs.current[index]=node;}} role="tab" type="button" id={prefix+"-tab-"+index} aria-selected={active===index} aria-controls={prefix+"-panel-"+index} tabIndex={active===index?0:-1} onKeyDown={keyboard} onClick={()=>setActive(index)}>{name}</button>)}</div><div role="tabpanel" tabIndex={0} id={prefix+"-panel-"+active} aria-labelledby={prefix+"-tab-"+active}>Treść: {names[active]}</div></section>;}`;
const dialog=`import {useState} from "react";import * as Dialog from "@radix-ui/react-dialog";import {NewTicketForm,type FormValues} from "./NewTicketForm";export function NewTicketDialog({onCreate}:{onCreate:(values:FormValues)=>Promise<void>}){const [open,setOpen]=useState(false);return <Dialog.Root open={open} onOpenChange={setOpen}><Dialog.Trigger asChild><button type="button">+ Nowy ticket</button></Dialog.Trigger><Dialog.Portal><Dialog.Overlay className="ticket-overlay"/><Dialog.Content className="ticket-dialog"><Dialog.Title>Nowy ticket</Dialog.Title><Dialog.Description>Wpisz dane nowego ticketu.</Dialog.Description><NewTicketForm onCreate={onCreate} onCreated={()=>setOpen(false)}/><Dialog.Close asChild><button type="button">Anuluj</button></Dialog.Close></Dialog.Content></Dialog.Portal></Dialog.Root>;}`;
const undo=`import {useEffect,useRef,useState} from "react";export type Row={id:number;title:string};export function TicketListWithUndo({onDeleteOnServer}:{onDeleteOnServer:(id:number)=>Promise<void>}){const [rows,setRows]=useState<Row[]>([{id:42,title:"API timeout"},{id:7,title:"Dokumentacja"}]),[pending,setPending]=useState<{row:Row;index:number}|null>(null),[deleting,setDeleting]=useState(false),[error,setError]=useState("");const callback=useRef(onDeleteOnServer);useEffect(()=>{callback.current=onDeleteOnServer;},[onDeleteOnServer]);useEffect(()=>{if(!pending)return;let active=true;const operation=pending;const timer=setTimeout(()=>{setDeleting(true);callback.current(operation.row.id).then(()=>{if(active)setPending(null);}).catch(()=>{if(active){setRows(current=>{const next=[...current];if(!next.some(row=>row.id===operation.row.id))next.splice(Math.min(operation.index,next.length),0,operation.row);return next;});setError("Nie udało się usunąć ticketu.");setPending(null);}}).finally(()=>{if(active)setDeleting(false);});},5000);return ()=>{active=false;clearTimeout(timer);};},[pending]);function remove(row:Row){if(pending)return;setError("");setPending({row,index:rows.findIndex(item=>item.id===row.id)});setRows(current=>current.filter(item=>item.id!==row.id));}function restore(){if(!pending||deleting)return;const operation=pending;setRows(current=>{const next=[...current];next.splice(Math.min(operation.index,next.length),0,operation.row);return next;});setPending(null);}return <section><h2>Tickety do uporządkowania</h2><ul>{rows.map(row=><li key={row.id}>{row.title}<button type="button" disabled={!!pending} onClick={()=>remove(row)}>Usuń {row.title}</button></li>)}</ul>{pending&&<div role="status">{deleting?"Trwa usuwanie ticketu.":"Usunięto z widoku. Możesz cofnąć przez 5 sekund."}{!deleting&&<button type="button" onClick={restore}>Cofnij</button>}</div>}{error&&<p role="alert">{error}</p>}</section>;}`;
const search=`import {useEffect,useState} from "react";const names=["API timeout","API eksportu","Dokumentacja"];export function DebouncedSearch(){const [draft,setDraft]=useState(""),[query,setQuery]=useState("");useEffect(()=>{const timer=setTimeout(()=>setQuery(draft),300);return ()=>clearTimeout(timer);},[draft]);const rows=names.filter(name=>name.toLowerCase().includes(query.toLowerCase()));return <section><label>Szukaj lokalnie<input type="search" value={draft} onChange={e=>setDraft(e.currentTarget.value)}/></label><ul>{rows.map(name=><li key={name}>{name}</li>)}</ul><p role="status">Wyników: {rows.length}</p></section>;}`;
const formTests=`// @vitest-environment jsdom
import {expect,test,vi} from "vitest";import {render,screen,waitFor} from "@testing-library/react";import userEvent from "@testing-library/user-event";import {NewTicketForm,type FormValues} from "./NewTicketForm";
test("błąd tytułu opisuje pole i przenosi fokus bez zapisu",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł")," abc ");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).not.toHaveBeenCalled();expect(screen.getByLabelText("Tytuł")).toHaveAttribute("aria-invalid","true");expect(screen.getByLabelText("Tytuł")).toHaveAccessibleDescription(/co najmniej 5 znaków/);expect(screen.getByLabelText("Tytuł")).toHaveFocus();});test("poprawne dane są przycięte i resetowane po sukcesie",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"  Błąd eksportu CSV  ");await user.type(screen.getByLabelText("Opis"),"  opis  ");await user.selectOptions(screen.getByLabelText("Priorytet"),"HIGH");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).toHaveBeenCalledExactlyOnceWith({title:"Błąd eksportu CSV",description:"opis",priority:"HIGH"});await waitFor(()=>expect(screen.getByLabelText("Tytuł")).toHaveValue(""));expect(screen.getByLabelText("Opis")).toHaveValue("");expect(screen.getByLabelText("Priorytet")).toHaveValue("NORMAL");});test("CRITICAL wymaga opisu i fokusuje właściwe pole",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"Awaria eksportu");await user.selectOptions(screen.getByLabelText("Priorytet"),"CRITICAL");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).not.toHaveBeenCalled();expect(screen.getByLabelText("Opis")).toHaveFocus();expect(screen.getByLabelText("Opis")).toHaveAccessibleDescription(/co najmniej 10 znaków/);await user.type(screen.getByLabelText("Opis"),"Długi opis awarii");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).toHaveBeenCalledExactlyOnceWith({title:"Awaria eksportu",description:"Długi opis awarii",priority:"CRITICAL"});});test("błąd zapisu nie usuwa szkicu, a poprawka pozwala ponowić",async()=>{const user=userEvent.setup(),onCreate=vi.fn<(values:FormValues)=>Promise<void>>().mockRejectedValueOnce(Error("sieć")).mockResolvedValue();render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"Błąd eksportu");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(await screen.findByRole("alert")).toHaveTextContent("Dane pozostają");expect(screen.getByLabelText("Tytuł")).toHaveValue("Błąd eksportu");await user.clear(screen.getByLabelText("Tytuł"));await user.type(screen.getByLabelText("Tytuł"),"Naprawiony eksport");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(onCreate).toHaveBeenCalledTimes(2);await waitFor(()=>expect(screen.getByLabelText("Tytuł")).toHaveValue(""));});test("nierozstrzygnięty zapis blokuje drugi klik",async()=>{const user=userEvent.setup();let finish!:()=>void;const onCreate=vi.fn<(values:FormValues)=>Promise<void>>(()=>new Promise<void>(resolve=>{finish=resolve;}));render(<NewTicketForm onCreate={onCreate}/>);await user.type(screen.getByLabelText("Tytuł"),"Awaria eksportu");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(screen.getByRole("button",{name:"Tworzenie…"})).toBeDisabled();await user.click(screen.getByRole("button",{name:"Tworzenie…"}));expect(onCreate).toHaveBeenCalledTimes(1);finish();await waitFor(()=>expect(screen.getByRole("button",{name:"Utwórz"})).toBeEnabled());});`;
const tabTests=`// @vitest-environment jsdom
import {expect,test} from "vitest";import {render,screen} from "@testing-library/react";import userEvent from "@testing-library/user-event";import {TicketSections} from "./TicketSections";
test("strzałka przenosi wybór i fokus, panel ma właściwą nazwę",async()=>{const user=userEvent.setup();render(<TicketSections/>);await user.tab();expect(screen.getByRole("tab",{name:"Szczegóły"})).toHaveFocus();await user.keyboard("{ArrowRight}");const activity=screen.getByRole("tab",{name:"Aktywność"});expect(activity).toHaveFocus();expect(activity).toHaveAttribute("aria-selected","true");expect(screen.getByRole("tabpanel")).toHaveAccessibleName("Aktywność");expect(screen.getByRole("tab",{name:"Szczegóły"})).toHaveAttribute("tabindex","-1");});test("Home, End i zawijanie obu kierunków",async()=>{const user=userEvent.setup();render(<TicketSections/>);await user.tab();await user.keyboard("{ArrowLeft}");expect(screen.getByRole("tab",{name:"Historia"})).toHaveFocus();await user.keyboard("{ArrowRight}");expect(screen.getByRole("tab",{name:"Szczegóły"})).toHaveFocus();await user.keyboard("{End}");expect(screen.getByRole("tab",{name:"Historia"})).toHaveAttribute("aria-selected","true");await user.keyboard("{Home}");expect(screen.getByRole("tab",{name:"Szczegóły"})).toHaveFocus();});test("kliknięcie wybiera panel i zachowuje powiązanie ARIA",async()=>{const user=userEvent.setup();render(<TicketSections/>);await user.click(screen.getByRole("tab",{name:"Historia"}));const tab=screen.getByRole("tab",{name:"Historia"}),panel=screen.getByRole("tabpanel");expect(tab).toHaveAttribute("aria-controls",panel.id);expect(panel).toHaveAttribute("aria-labelledby",tab.id);});`;
const dialogTests=`// @vitest-environment jsdom
import {expect,test,vi} from "vitest";import {render,screen,within,waitFor} from "@testing-library/react";import userEvent from "@testing-library/user-event";import {NewTicketDialog} from "./NewTicketDialog";
test("Escape zamyka modal i przywraca fokus wyzwalaczowi",async()=>{const user=userEvent.setup();render(<NewTicketDialog onCreate={vi.fn().mockResolvedValue(undefined)}/>);const opener=screen.getByRole("button",{name:"+ Nowy ticket"});await user.click(opener);expect(await screen.findByRole("dialog",{name:"Nowy ticket"})).toBeVisible();await waitFor(()=>expect(screen.getByLabelText("Tytuł")).toHaveFocus());await user.keyboard("{Escape}");await waitFor(()=>expect(screen.queryByRole("dialog")).not.toBeInTheDocument());expect(opener).toHaveFocus();});test("Tab zawija w obrębie modala, Shift+Tab wraca na koniec",async()=>{const user=userEvent.setup();render(<NewTicketDialog onCreate={vi.fn().mockResolvedValue(undefined)}/>);await user.click(screen.getByRole("button",{name:"+ Nowy ticket"}));const dialog=await screen.findByRole("dialog",{name:"Nowy ticket"}),cancel=within(dialog).getByRole("button",{name:"Anuluj"});await user.click(cancel);await user.click(screen.getByRole("button",{name:"+ Nowy ticket"}));const title=screen.getByLabelText("Tytuł");await waitFor(()=>expect(title).toHaveFocus());await user.tab({shift:true});expect(screen.getByRole("button",{name:"Anuluj"})).toHaveFocus();await user.tab();expect(title).toHaveFocus();});test("poprawny zapis zamyka dialog po potwierdzeniu",async()=>{const user=userEvent.setup(),onCreate=vi.fn().mockResolvedValue(undefined);render(<NewTicketDialog onCreate={onCreate}/>);const opener=screen.getByRole("button",{name:"+ Nowy ticket"});await user.click(opener);await user.type(screen.getByLabelText("Tytuł"),"Nowy ticket API");await user.click(screen.getByRole("button",{name:"Utwórz"}));await waitFor(()=>expect(screen.queryByRole("dialog")).not.toBeInTheDocument());expect(opener).toHaveFocus();expect(onCreate).toHaveBeenCalledTimes(1);});test("błąd zapisu pozostawia modal oraz dane",async()=>{const user=userEvent.setup();render(<NewTicketDialog onCreate={vi.fn().mockRejectedValue(Error("sieć"))}/>);await user.click(screen.getByRole("button",{name:"+ Nowy ticket"}));await user.type(screen.getByLabelText("Tytuł"),"Nowy ticket API");await user.click(screen.getByRole("button",{name:"Utwórz"}));expect(await screen.findByRole("alert")).toHaveTextContent("Nie udało");expect(screen.getByRole("dialog",{name:"Nowy ticket"})).toBeVisible();expect(screen.getByLabelText("Tytuł")).toHaveValue("Nowy ticket API");});`;
const timerTests=`// @vitest-environment jsdom
import {afterEach,expect,test,vi} from "vitest";import {act,cleanup,fireEvent,render,screen} from "@testing-library/react";import {TicketListWithUndo} from "./TicketListWithUndo";import {DebouncedSearch} from "./DebouncedSearch";
afterEach(()=>{cleanup();vi.clearAllTimers();vi.useRealTimers();});test("cofnięcie przywraca wiersz bez mutacji po czasie",async()=>{vi.useFakeTimers();const onDelete=vi.fn().mockResolvedValue(undefined);render(<TicketListWithUndo onDeleteOnServer={onDelete}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));expect(screen.queryByText("API timeout")).not.toBeInTheDocument();fireEvent.click(screen.getByRole("button",{name:"Cofnij"}));expect(screen.getByText("API timeout")).toBeVisible();await act(async()=>{await vi.advanceTimersByTimeAsync(6000);});expect(onDelete).not.toHaveBeenCalled();});test("brak cofnięcia wywołuje zapis dopiero na granicy 5 sekund",async()=>{vi.useFakeTimers();const onDelete=vi.fn().mockResolvedValue(undefined);render(<TicketListWithUndo onDeleteOnServer={onDelete}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));await act(async()=>{await vi.advanceTimersByTimeAsync(4999);});expect(onDelete).not.toHaveBeenCalled();await act(async()=>{await vi.advanceTimersByTimeAsync(1);});expect(onDelete).toHaveBeenCalledExactlyOnceWith(42);expect(screen.queryByRole("button",{name:"Cofnij"})).not.toBeInTheDocument();});test("błąd zapisu przywraca rekord i pokazuje alert",async()=>{vi.useFakeTimers();render(<TicketListWithUndo onDeleteOnServer={vi.fn().mockRejectedValue(Error("sieć"))}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));await act(async()=>{await vi.advanceTimersByTimeAsync(5000);});expect(screen.getByRole("alert")).toHaveTextContent("Nie udało się usunąć");expect(screen.getByText("API timeout")).toBeVisible();});test("unmount anuluje oczekującą mutację, nie udaje rollbacku rozpoczętego zapisu",async()=>{vi.useFakeTimers();const onDelete=vi.fn().mockResolvedValue(undefined);const view=render(<TicketListWithUndo onDeleteOnServer={onDelete}/>);fireEvent.click(screen.getByRole("button",{name:"Usuń API timeout"}));view.unmount();await act(async()=>{await vi.advanceTimersByTimeAsync(6000);});expect(onDelete).not.toHaveBeenCalled();});test("debounce filtruje dopiero po przerwie",async()=>{vi.useFakeTimers();render(<DebouncedSearch/>);fireEvent.change(screen.getByRole("searchbox",{name:"Szukaj lokalnie"}),{target:{value:"API"}});expect(screen.getByRole("status")).toHaveTextContent("Wyników: 3");await act(async()=>{await vi.advanceTimersByTimeAsync(299);});expect(screen.getByText("Dokumentacja")).toBeVisible();await act(async()=>{await vi.advanceTimersByTimeAsync(1);});expect(screen.getByRole("status")).toHaveTextContent("Wyników: 2");expect(screen.queryByText("Dokumentacja")).not.toBeInTheDocument();});`;
const exercises=[
['Utwórz userEvent.setup wewnątrz testu i oczekuj na każde click/type/keyboard.','Interakcje są asynchroniczną sekwencją zdarzeń.',formTests],
['Napisz NewTicketForm z kontrolowanymi polami i typowanym asynchronicznym onCreate.','Oddziel trim, walidację, zapis i reset po sukcesie.',form],
['Dodaj walidację tytułu po trim, aria-invalid i opis błędu przy polu.','Nie zaliczaj białych znaków do minimalnej treści.',form],
['Po błędnym tytule skup właściwe pole bez wywołania onCreate.','Samo pokazanie komunikatu nie zapewnia łatwej poprawy.',formTests],
['Dodaj regułę CRITICAL wymagającą opisu o długości co najmniej 10 po trim.','Błąd opisu ma kierować fokus do opisu, nie tytułu.',form],
['Przetestuj regułę zależną przez wybór opcji selectOptions i późniejszą poprawę.','Nie wywołuj handlera bezpośrednio.',formTests],
['Sprawdź poprawne dane callbacku, normalizację białych znaków i reset dopiero po sukcesie.','Reset przed await mógłby usunąć niezapisany szkic.',formTests],
['Po błędzie zapisu zachowaj dane, pokaż alert i pozwól poprawić oraz ponowić.','Nie zamieniaj catch na pozorny sukces.',formTests],
['Zabezpiecz podwójne wysłanie podczas nierozstrzygniętej Promise.','Ref pilnuje operacji, disabled opisuje stan kontrolek.',form],
['Przetestuj blokadę drugim kliknięciem, kontrolując Promise zamiast czasu sieci.','Sprawdź dokładnie jedno wywołanie adaptera.',formTests],
['Utwórz zakładki z roving tabindex, nazwą panelu i klawiaturową aktywacją automatyczną.','Tab ma prowadzić do aktywnej zakładki, strzałki do pozostałych.',tabs],
['Przetestuj ArrowRight: fokus, aria-selected oraz nazwę widocznego panelu.','Fokus i wybór są osobnymi asercjami.',tabTests],
['Sprawdź zawijanie ArrowLeft i ArrowRight oraz klawisze Home i End.','Granice listy to ważne zachowanie komponentu.',tabTests],
['Przetestuj aria-controls i aria-labelledby po kliknięciu zakładki.','Powiązania mają wskazywać rzeczywiste ID elementów.',tabTests],
['Zbuduj modal na sprawdzonym prymitywie Dialog z portalem, Title i Description.','Nie udawaj pełnej modalności samym aria-modal.',dialog],
['Sprawdź otwarcie i początkowy fokus w Tytule.','screen widzi też treść portalu w document.body.',dialogTests],
['Przetestuj Escape i powrót fokusu na przycisk wyzwalający.','Samo zniknięcie modala nie dowodzi przywrócenia fokusu.',dialogTests],
['Sprawdź Tab i Shift+Tab na granicy modala.','Nie wybieraj przypadkowego inputa z całego dokumentu.',dialogTests],
['Sprawdź zamknięcie po udanym zapisie oraz pozostanie otwartym po błędzie.','Przycisk zapisujący nie powinien być bezwarunkowym Dialog.Close.',dialogTests],
['Zaimplementuj lokalne ukrycie rekordu z 5-sekundowym oknem Cofnij przed wywołaniem adaptera usunięcia.','Nie nazywaj cofnięcia rollbackiem mutacji, której jeszcze nie wykonano.',undo],
['Przetestuj Cofnij i upewnij się, że po 6 sekundach adapter nadal nie został wywołany.','Tutaj fireEvent wywołuje celowo pojedyncze zdarzenie; test dotyczy zegara, nie pełnej sekwencji użytkownika.',timerTests],
['Sprawdź brak mutacji po 4999 ms i pojedynczą mutację po następnej milisekundzie.','Granica czasowa jest częścią kontraktu.',timerTests],
['Po błędzie usunięcia przywróć rekord na właściwą pozycję i pokaż alert.','Nie prezentuj usunięcia jako pewnego sukcesu.',undo],
['Sprawdź sprzątanie oczekującego timera przy unmount.','To nie dowodzi anulowania mutacji już wykonanej na serwerze.',timerTests],
['Napisz lokalną wyszukiwarkę z debounce 300 ms i cleanup starego timeoutu.','Draft i zastosowany filtr są różnymi stanami.',search],
['Przetestuj wyszukiwanie przed i po granicy czasu, używając act dla przesunięcia zegara.','Przesunięcie timera powodujące aktualizację React musi być objęte właściwą synchronizacją.',timerTests],
['Wyjaśnij, kiedy pojedyncze fireEvent jest nadal uzasadnione.','Preferencja user-event nie oznacza, że obsługuje każdą możliwą interakcję.',`Użyj fireEvent dla świadomie testowanego niskopoziomowego zdarzenia, którego user-event nie modeluje. Opisz założenie i nie przedstawiaj jednego dispatchEvent jako całego rzeczywistego kliknięcia. Standardowe pisanie, klikanie, wybór opcji i klawiaturę opisuj przez userEvent.`],
['Dodaj próbę czułości Escape w kopii modala.','Zablokuj obsługę Escape w Content i sprawdź, czy test zachowania to wykrywa.',`W kopii dodaj onEscapeKeyDown={event=>event.preventDefault()} do Dialog.Content. Test „Escape zamyka modal” ma zawieść, bo dialog pozostaje. Raport musi zawierać niezaliczoną asercję, nie tylko błąd środowiska. Przywróć poprawną implementację po próbie.`],
['Dodaj próbę czułości walidacji i klawiatury zakładek.','Każda próba ma być w osobnej kopii fixture.',`1. Usuń kontrolę minimalnej długości tytułu: test błędnego formularza ma wykryć wywołanie onCreate.
2. Zmień obsługiwany klawisz ArrowRight na nieistniejącą nazwę: test fokusu i aria-selected ma zawieść.
3. Nie uznawaj błędu importu za wykrycie mutanta. Potwierdź failing test w raporcie.`],
['Zaplanuj dodatkową próbę w prawdziwej przeglądarce dla modala i interakcji wskaźnika.','Jsdom nie odtwarza geometrii, zasłonięcia i każdego natywnego zachowania.',`Sprawdź widoczny modal na desktopie i telefonie, klawiaturę, powrót fokusu, tło i przewijanie. Otwórz i zamknij Escape oraz Anuluj. Sprawdź kliknięcia przy nakładających się elementach w prawdziwym layoucie. Testy user-event w jsdom opisuj jako testy symulowanego DOM, nie jako ukończony audyt wszystkich przeglądarek.`],
];
const quiz=[];const q=(question,answer,b,c,d,explanation,code)=>quiz.push([question,answer,b,c,d,explanation,...(code?[code]:[])]);
q('Dlaczego user-event bywa lepszy od pojedynczego fireEvent.click?','Modeluje interakcję z sekwencją zdarzeń i kontrolami dostępności działania','Zawsze uruchamia prawdziwą przeglądarkę','Nigdy nie wymaga await','Zastępuje każdą asercję','Pojedyncze zdarzenie nie reprezentuje całej interakcji.');
q('Gdzie tworzyć userEvent.setup w typowym przykładzie?','Wewnątrz testu przed interakcjami','Raz globalnie dla wszystkich niezależnych testów','W module produkcyjnego backendu','Wyłącznie w afterEach','Każdy test powinien mieć kontrolowaną sesję interakcji.');
q('Dlaczego await user.click jest ważne?','Test czeka na zakończenie modelowanej interakcji','Kliknięcie staje się synchronizacją bazy danych','Await zawsze gwarantuje sukces backendu','Bez await kompilacja usuwa button','Asynchroniczny test musi obejmować wykonanie działania.');
q('Co robi user.type?','Wpisuje tekst przez modelowaną sekwencję interakcji pola','Tylko bezpośrednio przypisuje zmienną useState','Wysyła HTTP POST dla każdego pola','Automatycznie zapisuje formularz','Sprawdzasz połączenie kontrolki i handlerów.');
q('Co robi user.clear?','Czyści zawartość pola przez interakcję','Resetuje wszystkie mocki','Usuwa QueryClient','Zamyka każdy modal','To operacja na kontrolce, nie całym środowisku testowym.');
q('Jak wybrać opcję select?','await user.selectOptions(select,"HIGH")','Bezpośrednio wywołać prywatny setPriority','Zmienić CSS selecta','Wywołać handler z pustym eventem','Test opisuje działanie użytkownika na kontrolce.');
q('Jak sprawdzić przejście fokusu klawiszem Tab?','await user.tab() i toHaveFocus','Tylko sprawdzić tabIndex w kodzie źródłowym','Zmienić className','Wywołać setFocus jako zamiennik interakcji','Atrybut i faktyczny fokus to osobne obserwacje.');
q('Jak wysłać Escape?','await user.keyboard("{Escape}")','user.type(input,"Escape") jako litery','Zmienić URL na Escape','Wywołać każdy handler ręcznie','Składnia keyboard opisuje klawisz, nie tekst do wpisania.');
q('Czego potrzebuje user-event przy fake timers?','advanceTimers zgodnego z runnerem','Zawsze delay:null jako naprawy','Rzeczywistego sleep 10 sekund','Wyłączenia wszystkich asercji','Opcja pozwala modelowanym zdarzeniom współpracować z kontrolowanym czasem.');
q('Dlaczego nie naprawiać zawieszającego się testu automatycznie przez delay:null?','Może zmienić model interakcji zamiast poprawić sterowanie timerami','Bo null jest zawsze błędem składni','Bo każda interakcja musi trwać realnie sekundę','Bo userEvent nie ma konfiguracji','Dokumentacja zaleca właściwe advanceTimers.');
q('Dlaczego opakować ręczne przesunięcie timera aktualizującego React w act?','Aby test synchronizował wynikające z niego aktualizacje UI','Aby timer wykonał zapis produkcyjny','Aby usunąć wszystkie efekty','Aby pominąć render','Synchronizacja ma odpowiadać źródłu aktualizacji.');
q('Czy wszystkie wywołania user-event trzeba dodatkowo ręcznie opakowywać w act?','Zwykle nie, korzystaj z integracji i await, a act dobierz do zewnętrznych aktualizacji','Tak, zawsze potrójnie','Nie, więc ręczne timery nigdy nie wymagają synchronizacji','Tak, zamiast await','Nie dodawaj mechanicznie niepotrzebnych warstw.');
q('Co sprawdza toHaveAccessibleDescription przy błędzie pola?','Opis powiązany z kontrolką, np. przez aria-describedby','Wyłącznie widoczny kolor błędu','Prywatny obiekt errors','Status HTTP','Test obejmuje semantyczne powiązanie komunikatu.');
q('Dlaczego sprawdzić fokus po walidacji?','Użytkownik ma łatwo poprawić właściwe pole','Fokus zapisuje dane na serwerze','Fokus automatycznie przyznaje uprawnienie','Fokus usuwa wszystkie błędy','Komunikat i kierowanie uwagi to różne części UX.');
q('Kiedy oceniać minimalną długość tytułu?','Po normalizacji trim zgodnej z kontraktem','Tylko przed trim','Po wywołaniu onCreate','Wyłącznie w klasie CSS','Białe znaki nie powinny udawać treści.');
q('Dlaczego form ma noValidate w przykładzie własnej walidacji?','Żeby handler mógł kontrolować pokazane komunikaty także dla błędnego wejścia','Żeby wyłączyć walidację backendu','Żeby każdy input zawsze był poprawny','Żeby ominąć TypeScript','To jawna decyzja dotycząca klientowego formularza.');
q('Co sprawdza test CRITICAL bez opisu?','Regułę zależną od wartości innego pola','Wyłącznie liczbę opcji select','Przeładowanie strony','Nowy status HTTP','Warunki zależne wymagają osobnych przypadków.');
q('Które pole powinno otrzymać fokus przy błędzie opisu CRITICAL?','Opis','Zawsze tytuł','Zawsze przycisk Anuluj','Body dokumentu','Kieruj użytkownika do właściwej przyczyny.');
q('Kiedy czyścić formularz po wysłaniu?','Po potwierdzonym sukcesie','Przed await adaptera','Zawsze w catch','Już przy hoverze przycisku','Błąd zapisu nie powinien usuwać szkicu.');
q('Co zachować po błędzie onCreate?','Dane użytkownika i możliwość poprawy lub ponowienia','Tylko pusty formularz','Fałszywy komunikat sukcesu','Wyłącznie stack trace','Obsługa błędu jest częścią przepływu formularza.');
q('Dlaczego stan busy nie wystarcza jako pełna gwarancja idempotencji serwera?','Żądanie można wysłać inną drogą lub powtórzyć po niepewnym wyniku','Bo busy nigdy nie działa w React','Bo każdy POST jest automatycznie idempotentny','Bo disabled zapisuje token','UI ogranicza przypadkowe powtórzenia, ale nie zastępuje kontraktu API.');
q('Jak przetestować zapis, który jeszcze nie skończył się?','Kontrolowaną Promise adaptera','Losowym opóźnieniem sieci produkcyjnej','Tylko sprawdzając nazwę funkcji','Natychmiastowym mockResolvedValue bez oceny pending','Możesz sprawdzić UI i liczbę wywołań przed rozwiązaniem.');
q('Dlaczego ref sending może uzupełniać busy?','Chroni przed rozpoczęciem drugiej operacji w tym samym cyklu działania','Zastępuje wszystkie rendery','Jest tokenem uwierzytelnienia','Automatycznie czeka na backend','Wskaźnik logiczny i prezentacja UI mają różne role.');
q('Co oznacza roving tabindex w zakładkach?','Tylko aktywna zakładka jest zwykłym przystankiem Tab, pozostałe obsługują strzałki','Wszystkie przyciski zawsze mają tabindex=9','Każda strzałka zamyka stronę','Panele nie mają żadnych nazw','To model klawiaturowej nawigacji po zestawie zakładek.');
q('Co powinno zmienić ArrowRight w modelu automatycznej aktywacji?','Fokus, wybraną zakładkę i powiązany panel','Wyłącznie klasę hover','Tylko adres backendu','Wszystkie kontrolki na disabled','Test powinien sprawdzić więcej niż sam tekst.');
q('Po co Home i End w testach zakładek?','Sprawdzają przejście do skrajnych zakładek','Są nazwami statusów HTTP','Zastępują wszystkie strzałki','Zapisują panel','Granice zestawu są odrębnymi przypadkami interakcji.');
q('Co oznacza aria-selected?','Która zakładka jest wybrana','Status poprawności formularza','Czy operacja usuwania się udała','Kod odpowiedzi API','Fokus nie musi sam określać wyboru w każdym modelu.');
q('Po co aria-controls na tab?','Wskazuje ID powiązanego panelu','Wykonuje automatycznie fetch','Tworzy rolę administratora','Zamyka dialog','Atrybut ma wskazywać rzeczywisty element.');
q('Po co aria-labelledby na tabpanel?','Nadaje nazwę na podstawie zakładki','Zastępuje klawiaturę','Zapisuje formularz','Uruchamia nawigację','Relacja wspiera orientację w widoku.');
q('Czy kliknięcie zakładki i obsługa klawiatury wymagają osobnych testów?','Tak, jeden wariant może działać, gdy drugi jest uszkodzony','Nie, click sprawdza każdy klawisz','Nie, typy gwarantują klawiaturę','Tak, bo każdy test musi być identyczny','To różne drogi interakcji.');
q('Czy role=dialog i aria-modal same implementują pułapkę fokusu?','Nie','Tak, zawsze','Tak, po dodaniu koloru tła','Tak, jeżeli dialog jest w portalu','Semantyka i zachowanie to oddzielne wymagania.');
q('Po co użyć sprawdzonego prymitywu Dialog?','Aby oprzeć modal na zdefiniowanej obsłudze fokusu, tła i zamykania','Aby usunąć potrzebę testów','Aby zastąpić formularz backendem','Aby ukryć wszystkie komunikaty','Nadal trzeba zweryfikować integrację i właściwe treści.');
q('Dlaczego modal potrzebuje Title i Description?','Zapewniają zrozumiałą nazwę i kontekst','Nadają mu status 200','Automatycznie zapisują dane','Blokują każdy fetch','Nazwana powierzchnia ułatwia obsługę i testowanie.');
q('Czy screen może znaleźć treść portalu?','Tak, jeśli jest w document.body objętym zapytaniami','Nie, portal zawsze jest poza DOM','Nie, wymagany jest testId','Tak, ale tylko jako screenshot','Zakres screen zwykle obejmuje body, nie tylko container renderu.');
q('Co sprawdzić po Escape w modalu?','Zniknięcie dialogu i powrót fokusu na wyzwalacz','Wyłącznie zmianę opacity','Zapis formularza mimo Anuluj','Usunięcie ticketu','Zamknięcie ma pozostawić użytkownika w sensownym miejscu.');
q('Dlaczego testować Shift+Tab na pierwszym polu?','Sprawdza zawijanie na koniec obszaru modalnego','Uruchamia HTTP PATCH','Zastępuje test nazwy dialogu','Czyści szkic','Pułapka fokusu musi działać w obu kierunkach.');
q('Dlaczego przycisk Utwórz nie powinien bezwarunkowo być Dialog.Close?','Zamknąłby modal także przed potwierdzeniem zapisu lub po błędzie','Bo button nie może być w dialogu','Bo portal wyłącza submit','Bo każdy formularz musi pozostać otwarty na zawsze','Zamknięcie po sukcesie musi wynikać z wyniku operacji.');
q('Co ma wykazać test błędu zapisu w modalu?','Dialog i szkic pozostają, a użytkownik widzi alert','Wszystko znika bez komunikatu','Fokus zawsze trafia na body','Dane są usuwane z backendu','Negatywna ścieżka powinna dawać możliwość dalszej pracy.');
q('Co oznacza Cofnij w pokazanym opóźnionym usunięciu?','Anulowanie oczekującej mutacji i przywrócenie lokalnego wiersza','Rollback zakończonej transakcji serwera','Usunięcie całej historii','Przywrócenie konta','Mutacja jest odkładana do końca okna cofnięcia.');
q('Kiedy adapter usuwania powinien zostać wywołany bez cofnięcia?','Dopiero na granicy 5 sekund','Natychmiast przy ukryciu wiersza','Po losowym czasie','Nigdy','Próg czasowy jest częścią kontraktu tej implementacji.');
q('Dlaczego sprawdzić 4999 ms i następną milisekundę?','Wykrywa zbyt wczesną mutację i poprawną granicę','Bo realna sieć ma dokładnie takie czasy','Bo 4999 zawsze uruchamia wszystkie timery','Bo nie wolno używać 5000','Kontrolowany zegar pozwala ocenić warunek brzegowy.');
q('Co powinno nastąpić po Cofnij przed upływem czasu?','Wiersz wraca, timer jest anulowany, adapter nie zostaje wywołany','Adapter usuwa go mimo wszystko','Wszystkie dane trafiają do query string','Router zamyka kartę','Przetestuj zarówno widok, jak i brak mutacji.');
q('Dlaczego po błędzie usunięcia przywrócić rekord?','Lokalny widok nie powinien udawać potwierdzonego usunięcia','Bo każdy błąd usuwa konto','Bo serwer zawsze wykonał rollback','Bo role=status nie może być puste','Pokazany adapter odrzuca operację; UI ma zachować czytelną ścieżkę naprawy.');
q('Czy anulowanie timera przy unmount wycofuje mutację, która już wystartowała?','Nie','Tak, clearTimeout cofa bazę','Tak, cleanup cofa HTTP','Tak, userEvent cofa serwer','Oczekująca praca i rozpoczęty zapis mają inny cykl życia.');
q('Dlaczego callback adaptera w refie nie restartuje 5-sekundowego okna przy nowej referencji props?','Timer zależy od konkretnej operacji, a callback może być aktualny osobno','Bo ref automatycznie zapisuje czas w URL','Bo wszystkie funkcje mają tę samą tożsamość','Bo efekty nie mają zależności','Oddziel aktualność zależności od rozpoczętego czasu operacji.');
q('Co powinno stać się z Cofnij po rozpoczęciu właściwej mutacji?','Nie może obiecywać anulowania już rozpoczętego zapisu','Musi zawsze cofnąć bazę','Powinno ukryć wszystkie błędy','Powinno resetować timer bez końca','UI ma opisywać rzeczywiste możliwości operacji.');
q('Dlaczego wyszukiwarka ma draft i query?','Wpisany tekst i zastosowany filtr mają różne momenty aktualizacji','Bo potrzebuje dwóch losowych kopii tych samych danych','Bo URL jest zawsze wymagany','Bo React nie obsługuje jednego pola','Debounce świadomie opóźnia zastosowanie wartości.');
q('Co ma wykazać test po 299 ms wyszukiwania?','Poprzedni wynik nadal obowiązuje','Nowy filtr już musi być pewnym sukcesem','Pole ma być wyczyszczone','Wszystkie dane mają zniknąć','Przed granicą nie powinno być przedwczesnego zastosowania.');
q('Po co cleanup poprzedniego timeoutu debounce?','Żeby starszy tekst nie zastosował się po nowszym','Żeby usunąć wszystkie dane aplikacji','Żeby przyspieszyć sieć','Żeby cofnąć zapis backendu','Timer należy do konkretnego szkicu.');
q('Czy user-event w jsdom sprawdza fizyczne zasłonięcie przycisku w layoucie?','Nie odtwarza pełnej geometrii prawdziwej przeglądarki','Tak, zawsze pixel-perfect','Tak, bo ma pointerEventsCheck','Tak, jeśli przycisk ma etykietę','Model interakcji ma istotne ograniczenia środowiska.');
q('Czym jest pointer-events:none względem user-event?','Jednym z warunków interakcji kontrolowanych przez bibliotekę','Gwarancją całego rzeczywistego layoutu','Sposobem autoryzacji','Zamiennikiem disabled we wszystkich kontekstach','Sprawdzenie tego stylu nie jest pełnym testem geometrii.');
q('Kiedy fireEvent pozostaje uzasadnione?','Dla świadomie modelowanego zdarzenia nieobsługiwanego przez user-event','Zawsze zamiast interakcji użytkownika','Nigdy w żadnym przypadku','Tylko po usunięciu asercji','Opisuj założenia i granicę testu.');
q('Czy wpisanie stringa Escape do inputa jest równoważne klawiszowi Escape?','Nie','Tak, zawsze','Tak, jeżeli jest w nawiasach tekstowych','Tak, jeżeli pole ma autofocus','Keyboard syntax rozróżnia klawisze i tekst.');
q('Co daje typowany vi.fn<(values:FormValues)=>Promise<void>>()?','Powiązanie mocka z kontraktem callbacku','Automatyczny zapis backendu','Zastąpienie asercji danych','Gwarancję pełnej dostępności','Typy wspierają poprawne użycie, a test nadal ocenia runtime.');
q('Dlaczego callback z poprawnymi danymi nie wystarcza jako jedyna asercja formularza?','UI może nie wyczyścić pól lub źle obsłużyć pending i błąd','Bo mock nie może mieć argumentów','Bo formularz jest wyłącznie wizualny','Bo wszystkie callbacki są takie same','Przepływ użytkownika obejmuje więcej niż samo wywołanie.');
q('Co zrobić po zmianie implementacji obsługi klawiatury?','Sprawdzić zachowanie przez user.keyboard i fokus','Wyłącznie porównać nazwy handlerów','Zawsze zaktualizować test bez oceny','Pominąć przypadki Home i End','Testy powinny oceniać działanie, nie prywatny sposób implementacji.');
q('Co ma wykryć mutant blokujący Escape w modalu?','Dialog pozostaje po klawiszu, więc test zamknięcia zawodzi','Wyłącznie zmianę liczby importów','Brak pakietu npm','Dowolny exit code niezależnie od raportu','Dowodem jest niezaliczona asercja zachowania.');
q('Co ma wykryć mutant usuwający walidację tytułu?','Błędne dane trafiają do onCreate zamiast zostać zatrzymane','Zawsze błąd stylu CSS','Wyłącznie zmianę wersji Reacta','Tylko ostrzeżenie kompilatora o nazwie funkcji','Test kontroluje niedozwolony skutek.');
q('Czy pomyślny test jsdom gwarantuje identyczne zachowanie wszystkich przeglądarek?','Nie','Tak, także mobilne zamknięcie procesu','Tak, user-event jest silnikiem Chrome','Tak, jeżeli działa Tab','Potrzebne są uzupełniające testy właściwego środowiska.');
q('Dlaczego nie testować interakcji przez bezpośrednie wywołanie onKeyDown z elementu React?','Pomija powiązanie DOM, fokus i drogę zdarzeń','Bo funkcje nigdy nie mogą być wywoływane','Bo userEvent używa HTTP','Bo TypeScript uniemożliwia eventy','Przepływ użytkownika obejmuje rzeczywiste kontrolki.');
q('Co znaczy poprawny fokus po zamknięciu dialogu?','Użytkownik wraca do sensownego wyzwalacza lub zgodnego z przepływem celu','Zawsze fokus na body','Zawsze usunięcie wszystkich tabindex','Zawsze fokus na niewidocznym inputie','Test powinien odpowiadać projektowanemu przepływowi.');
q('Dlaczego unikalne ID pól jest ważne przy kilku formularzach?','Label i opis błędu muszą wskazywać właściwą kontrolkę','Bo ID są tokenami dostępu','Bo React wymaga stałego globalnego title','Bo tylko jeden formularz może istnieć w aplikacji','useId pomaga uniknąć kolizji semantycznych.');
q('Czy role=status i role=alert są zawsze wymienne?','Nie, informacja o postępie i pilny błąd mają inny charakter','Tak, to wyłącznie klasy CSS','Tak, jeśli oba są div','Nie, bo status działa tylko na serwerze','Dobierz komunikat do znaczenia i pilności.');
q('Dlaczego należy posprzątać timery po teście interakcji?','Mogłyby wykonać pracę w innym teście','Bo inaczej usuwają pakiet React','Bo vi.useRealTimers zawsze zapisuje UI','Bo test nie może mieć wielu timerów','Izolacja obejmuje asynchroniczne zasoby.');
q('Co powinno towarzyszyć optimistic UI usuwania?','Jasny stan oczekiwania i obsługa błędu rzeczywistego zapisu','Założenie, że backend nigdy nie zawodzi','Ukrywanie alertów','Zawsze usunięcie pozycji z bazy przed pytaniem','Widok i wynik operacji muszą pozostać spójne.');
q('Dlaczego warto przetestować ponowienie po poprawieniu pola?','Pierwszy błąd nie może trwale zablokować poprawnego wysłania','Bo każda walidacja musi odmontować formularz','Bo stan errors ma być globalny','Bo userEvent nie obsługuje clear','Odzyskiwanie po błędzie jest częścią kontraktu.');
q('Co sprawdzać przy ograniczeniu akcji do jednego pending usunięcia?','Pozostałe kontrolki nie rozpoczynają sprzecznej operacji podczas oczekiwania','Tylko kolor tła','Zawsze usunięcie wszystkich wierszy','Brak jakiegokolwiek komunikatu','UI powinno jasno określać obsługiwany model współbieżności.');
q('Dlaczego nie nazywać testu lokalnej wyszukiwarki testem HTTP?','Nie wykonuje rzeczywistego żądania do endpointu','Bo każdy filtr musi być w bazie','Bo tekst ma format API','Bo user-event nie działa z lokalnym stanem','Opis testu ma zgadzać się z jego rzeczywistą granicą.');
q('Co ma być widoczne przy trwającym zapisie formularza?','Czytelny stan pracy i kontrolki zgodne z możliwością działania','Zawsze sukces przed odpowiedzią','Surowy token requestu','Losowy procent bez danych','Użytkownik powinien wiedzieć, że operacja trwa.');
